import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { triggerDeployHook } from "./deploy-hook";

describe("triggerDeployHook", () => {
  beforeEach(() => {
    vi.stubGlobal("fetch", vi.fn());
  });

  afterEach(() => {
    vi.unstubAllGlobals();
    vi.restoreAllMocks();
  });

  it("succeeds on the first attempt", async () => {
    vi.mocked(fetch).mockResolvedValue(new Response(null, { status: 200 }));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result).toEqual({ ok: true, attempts: 1 });
    expect(fetch).toHaveBeenCalledTimes(1);
  });

  it("retries once after a network failure and then succeeds", async () => {
    vi.mocked(fetch)
      .mockRejectedValueOnce(new Error("network down"))
      .mockResolvedValueOnce(new Response(null, { status: 200 }));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result).toEqual({ ok: true, attempts: 2 });
  });

  it("treats a non-2xx response as a failure worth retrying", async () => {
    vi.mocked(fetch)
      .mockResolvedValueOnce(new Response(null, { status: 503 }))
      .mockResolvedValueOnce(new Response(null, { status: 200 }));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result.ok).toBe(true);
    expect(fetch).toHaveBeenCalledTimes(2);
  });

  it("gives up after exhausting every retry", async () => {
    vi.mocked(fetch).mockRejectedValue(new Error("network down"));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result.ok).toBe(false);
    expect(result.attempts).toBe(3);
    expect(fetch).toHaveBeenCalledTimes(3);
  });
});

import { sql } from "drizzle-orm";
import { integer, sqliteTable, text } from "drizzle-orm/sqlite-core";

// A site is a customer's hosted blog — the tenant every post and revision
// belongs to. `deployHookUrl` is the webhook the API calls after a publish;
// see deploy-hook.ts for what happens when that call fails.
export const sites = sqliteTable("sites", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  name: text("name").notNull(),
  slug: text("slug").notNull().unique(),
  deployHookUrl: text("deploy_hook_url").notNull(),
  createdAt: text("created_at")
    .notNull()
    .default(sql`(current_timestamp)`),
});

export const posts = sqliteTable("posts", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  siteId: integer("site_id")
    .notNull()
    .references(() => sites.id),
  title: text("title").notNull(),
  slug: text("slug").notNull(),
  body: text("body").notNull(),
  status: text("status", { enum: ["draft", "published"] })
    .notNull()
    .default("draft"),
  createdAt: text("created_at")
    .notNull()
    .default(sql`(current_timestamp)`),
  updatedAt: text("updated_at")
    .notNull()
    .default(sql`(current_timestamp)`),
});

// A snapshot of a post's title and body, written every time it is published.
// The post row holds the current draft; a revision is the historical record
// of what actually went out.
export const revisions = sqliteTable("revisions", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  postId: integer("post_id")
    .notNull()
    .references(() => posts.id),
  title: text("title").notNull(),
  body: text("body").notNull(),
  createdAt: text("created_at")
    .notNull()
    .default(sql`(current_timestamp)`),
});

