import { lookup } from "node:dns/promises";
import { rootLogger } from "../shared/logger";

const logger = rootLogger.child("deploy-hook");

const MAX_ATTEMPTS = 3;
const RETRY_DELAY_MS = 250;
const ALLOWED_PROTOCOLS = new Set(["https:"]);

export interface DeployHookResult {
  readonly ok: boolean;
  readonly attempts: number;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function isPrivateIPv4(address: string): boolean {
  const octets = address.split(".").map(Number);
  if (octets.length !== 4 || octets.some((n) => !Number.isInteger(n) || n < 0 || n > 255)) {
    return true; // not a well-formed IPv4 literal — fail closed
  }
  const [a, b, c] = octets;
  if (a === 0) return true; // "this network"
  if (a === 10) return true; // RFC1918
  if (a === 127) return true; // loopback
  if (a === 100 && b >= 64 && b <= 127) return true; // carrier-grade NAT
  if (a === 169 && b === 254) return true; // link-local, incl. cloud metadata at 169.254.169.254
  if (a === 172 && b >= 16 && b <= 31) return true; // RFC1918
  if (a === 192 && b === 168) return true; // RFC1918
  if (a === 192 && b === 0 && c === 0) return true; // IETF protocol assignments
  if (a >= 224) return true; // multicast, reserved, and broadcast
  return false;
}

function isPrivateIPv6(address: string): boolean {
  const normalized = address.toLowerCase();
  if (normalized === "::1" || normalized === "::") return true; // loopback / unspecified
  const mapped = normalized.match(/^::ffff:(\d+\.\d+\.\d+\.\d+)$/);
  if (mapped) return isPrivateIPv4(mapped[1]);
  const firstGroup = normalized.split(":")[0];
  if (/^fe[89ab][0-9a-f]$/.test(firstGroup)) return true; // link-local, fe80::/10
  if (/^f[cd][0-9a-f]{2}$/.test(firstGroup)) return true; // unique local, fc00::/7
  return false;
}

async function resolvesToPublicAddress(hostname: string): Promise<boolean> {
  const bareHostname = hostname.replace(/^\[|\]$/g, "");
  let addresses: { address: string; family: number }[];
  try {
    addresses = await lookup(bareHostname, { all: true, verbatim: true });
  } catch {
    return false; // an unresolvable host is never safe to call
  }
  if (addresses.length === 0) return false;
  return addresses.every(({ address, family }) =>
    family === 6 ? !isPrivateIPv6(address) : !isPrivateIPv4(address),
  );
}

/**
 * A site's `deployHookUrl` is plain text a customer fills in, not a URL this
 * app chose — this is the one place that value ever turns into an outbound
 * request, so it's the one place that has to refuse an unsafe one. Rejects
 * anything but a plain `https://` URL whose host resolves to a public
 * address, so a hook pointed at loopback, an RFC1918 range, or a cloud
 * metadata endpoint (169.254.169.254) can't turn a publish into a request
 * against our own infrastructure.
 *
 * This doesn't defend against DNS rebinding — a host that resolves here to a
 * public address but to a private one by the time `fetch` connects a moment
 * later. Closing that fully needs pinning the connection to the address
 * checked here, which is a bigger change than this cut needs.
 */
export async function isSafeDeployHookUrl(rawUrl: string): Promise<boolean> {
  let parsed: URL;
  try {
